onPointerMove → event => { const press = backdropPress.current; // Eight CSS pixels is a local tap tolerance, not a universal gesture standard. if (press && (event.target !== event.currentTarget || Math.hypot(event.clientX - press.x, event.clientY - press.y) > 8)) press.moved = true; }
onPointerUp → event => { // Touch may implicitly capture the pointer; its event target can remain the // backdrop even after the finger has crossed into the dialog. const hit = document.elementFromPoint?.(event.clientX, event.clientY); if (event.target !== event.currentTarget || (hit && hit !== event.currentTarget) || event.pointerId !== backdropPress.current?.id) backdropPress.current = null; }
onPointerCancel → () => { backdropPress.current = null; }
onClick → event => { const press = backdropPress.current; backdropPress.current = null; if (event.target === event.currentTarget && press && !press.moved) onClose(); }

